ROOT=Path(__file__).resolve().parents[1];SRC=Path('/workspace/shared/atlas-research/company-onboarding/FN/public');OUT=ROOT/'dist/data/incremental-FN-2026-10-18-v1';OUT.mkdir(exist_ok=True,parents=True)
