def clean(x):
 if isinstance(x,list):return [clean(v)for v in x]
 if isinstance(x,dict):return {k:clean(v)for k,v in x.items()if k not in ['localPath','localFile','directory','file']}
 return x
def write(n,x):(OUT/n).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
source={k:clean(load(v))for k,v in {'operating':'forecast-defaults-v1.json','capital':'capital-claims-v1.json','normalizedCapital':'normalized-capital-v1.json','costOfCapital':'cost-of-capital-v1.json','research':'research.json','guidanceTrackRecord':'guidance-track-record.json','segments':'segment-history.json','sources':'source_manifest.json'}.items()}
source['publicExportManifest']=manifest
write('FN-v1-source.json',source)
for old,new in [('history-10fy.json','FN-history-v1.json'),('independent-audit.json','FN-v1-audit.json'),('research-notes.md','FN-full-research-v1.md'),('claim_allocation.py','FN-source-allocation-v1.py')]: (OUT/new).write_bytes((SRC/old).read_bytes())
p='./data/incremental-FN-2026-10-18-v1/'
id={'packageVersion':'incremental-FN-2026-10-18-v1','version':'2026-10-18-fn-dated-v1','ticker':'FN','currency':'USD','informationAsOf':'2026-10-18','discountOrigin':'2026-06-26','sourceSHA256':sha(SRC/'forecast-defaults-v1.json'),'bridgeSourceSHA256':sha(SRC/'capital-claims-v1.json'),'packagedSourceSHA256':sha(OUT/'FN-v1-source.json'),'auditSHA256':sha(OUT/'FN-v1-audit.json'),'packagedHistorySHA256':sha(OUT/'FN-history-v1.json'),'sourcePath':p+'FN-v1-source.json','auditPath':p+'FN-v1-audit.json','historyPath':p+'FN-history-v1.json','reportPath':p+'FN-v1.html','fullReportPath':p+'FN-full-research-v1.md','fullReportSHA256':sha(OUT/'FN-full-research-v1.md'),'allocationSourcePath':p+'FN-source-allocation-v1.py','allocationSourceSHA256':sha(OUT/'FN-source-allocation-v1.py')}
prose={
'scope':('June 26, 2026 financial, capital and discount origin; information through October 18, 2026. This is retrospective conditional research using later information and rates. It is not an as-known-at-origin backtest or a current share-price target. Current equity and quote comparisons are blocked.','财务、资本及折现基准日为 2026 年 6 月 26 日，信息截至 2026 年 10 月 18 日。这是使用较后信息及利率的回溯条件性研究，不是基准日当时已知信息回测，也不是当前股价目标。当前股权价值及报价比较已禁用。'),
'summary':('Fabrinet is a USD-reporting optical and precision-manufacturing business. NYSE FN is an ordinary share, not an ADR. Three analyst operating scenarios are combined with source-dated assets, claims and a jointly solved employee-award and Amazon-warrant allocation. No market share price is inserted into the solver.','Fabrinet 是以美元报告的光学及精密制造企业。纽约证券交易所 FN 为普通股，并非 ADR。三个分析经营情景结合日期对应的资产、请求权，以及员工奖励和亚马逊认股权证的联立分配。求解器不代入市场股价。'),
'growth':('The forecast separates data-center, communications and automotive/industrial/other revenue. FY2027 base revenue is 6,227.200 million USD versus reported FY2026 revenue of 4,641.097 million. Customer concentration, AI optics ramps, program transfer, qualification timing and capacity utilization create correlated risks. Named downside and upside cases are analyst paths, not issuer guidance or probability estimates.','预测分别建模数据中心、通信及汽车／工业／其他收入。2027 财年基准收入为 62.272 亿美元，2026 财年报告收入为 46.411 亿美元。客户集中、AI 光学产能爬坡、项目转移、认证时点及产能利用率带来关联风险。命名下行和上行情景属于分析路径，不是公司指引或概率估计。'),
'profitability':('Economic margins retain recurring future employee-grant cost of 0.75% of sales and new commercial incentives of 0.10%. Illustrative legacy RSU, PSU and Amazon-warrant amortization is subtracted and reversed equally, producing zero operating-value uplift. Existing awards and warrants receive value once in the coupled allocation. Future grants are not diluted again.','经济利润率保留收入 0.75% 的持续未来员工授予成本及 0.10% 的新商业激励成本。示例旧 RSU、PSU 和亚马逊认股权证摊销等额扣除并转回，不提高经营价值。现有奖励及权证在联立分配中仅计值一次，未来授予不再重复稀释。'),
'capital':('Historical operating NWC excludes fixed-asset payables, cash, taxes, severance and leases. The forecast explicitly funds cash capex, operating NWC and required cash growth. June fixed-asset payables of 86.018 million are netted from opening funded capital and settled once in FY2027 cash investment; they are never another bridge claim. The July 27 facility purchase remains in FY2027 capex. The later August borrowing is not a June debt or free cash credit.','历史经营营运资本排除固定资产应付款、现金、税款、离职义务及租赁。预测明确为现金资本开支、经营营运资本及所需现金增长提供资金。六月固定资产应付款 8,601.8 万美元从期初已出资资本扣除，并仅在 2027 财年现金投资结算一次，不另列资本桥请求权。7 月 27 日厂房购买保留在 2027 财年资本开支；较后八月借款不是六月债务或免费现金收益。'),
'funding':('Required operating cash is fixed at 3% of the following year’s sales. The editable investment input is before the change in this reserve. Every edited or simulated revenue path recalculates both the opening reserve and each annual cash change. Total cash investment equals the editable pre-reserve amount plus the required-cash change. The fixed 86.018 million FY2027 payable settlement is inside the pre-reserve amount and never scales or repeats. Terminal NOPAT × growth / ROIC already funds cash. The source 2–4% range requires a complete capital-policy rebuild and is not an independent bridge-only control.','所需经营现金固定为下一年度收入的 3%。可编辑投资输入不含该储备的变化。每条编辑或模拟收入路径都会重新计算期初储备及逐年现金变化。现金总投资＝可编辑储备前金额＋所需现金变化。2027 财年固定应付款结算 8,601.8 万美元已含在储备前金额中，不会缩放或重复。终值 NOPAT×增长率／ROIC 已包含现金资金需求。来源中的 2–4% 区间需要完整重建资本政策，并非可独立调整的资本桥控件。'),
'wacc':('The base, downside and upside nominal USD WACCs are 11.5%, 13.5% and 10%. These are analyst risk judgments using dated market context, not observed company WACCs or price-implied assumptions. The warrant uses October 16 interpolated 5–7 year Treasury input 4.922002%, applied directly in exp(−rT), and 5.711157 years from the June origin to March 12, 2032. Grant-date volatility 45.2% is a proxy, not current implied volatility.','基准、下行和上行名义美元 WACC 分别为 11.5%、13.5% 和 10%。它们是使用日期对应市场背景的分析风险判断，并非可观测的公司 WACC 或股价隐含假设。权证使用 10 月 16 日五至七年美国国债插值输入 4.922002%，直接用于 exp(−rT)，期限为六月基准日至 2032 年 3 月 12 日的 5.711157 年。授予日波动率 45.2% 为代理，并非当前隐含波动率。'),
 'tax':('Opening income-tax payable is 63.469 million USD, including 57.447 million of Pillar Two top-up tax. The entire opening payable is deducted once outside forward operating-income taxes. This is separate from the 56.743 million Raytek nonoperating gain, which is excluded from EBIT. The optional repatriation-tax claim is conditional on cash access.','期初应付所得税为 6,346.9 万美元，其中包含第二支柱补足税 5,744.7 万美元。期初应付款全额在未来经营所得税之外仅扣除一次。这与已排除于 EBIT 的 Raytek 非经营收益 5,674.3 万美元分别处理。可选汇回税请求权取决于现金使用假设。'),
 'terminal':('Base terminal policy is 2.5% growth, 9.5% economic margin, 20% operating tax, 20% terminal ROIC on beginning funded capital and 11.5% WACC. Downside and upside use their separately stated policies. Terminal investment equals NOPAT × growth / ROIC, including required cash. The final explicit FCFF transition is disclosed rather than silently repaired. Terminal normalization is an editable sensitivity.','基准终值政策为增长 2.5%、经济利润率 9.5%、经营税率 20%、期初已出资资本口径终值 ROIC 20% 和 WACC 11.5%。下行及上行使用各自明确政策。终值投资＝NOPAT×增长率／ROIC，包含所需现金。最后明确年度 FCFF 过渡保持披露，不会暗中修正。终值规范化为可编辑敏感性。'),
 'claims':('Unrestricted cash and investments are 875.055 million USD, less the dynamically funded 3% reserve. Raytek value ranges from 32.360 million cost to 89.103 million carrying value; neither is verified realizable cash. Deduct opening tax 63.469 and severance 34.095 once. Common shares are 35.834864 million. Full legacy awards are 0.306261 million, with 0.281793 expected-vesting alternative. Amazon warrants range from 0.085942 vested to 0.381922 maximum at USD208.48 strike. The solver allocates the same equity pool among ordinary shares, zero-strike awards and warrant fair value, with no second exercise-proceeds credit or warrant-share dilution.','非受限现金及投资为 8.75055 亿美元，减动态出资的 3% 储备。Raytek 价值区间为成本 3,236 万至账面价值 8,910.3 万美元；两者均非已验证可变现现金。期初税款 6,346.9 万及离职义务 3,409.5 万美元各扣除一次。普通股为 3,583.4864 万股。完整旧奖励为 30.6261 万股，预计归属替代值为 28.1793 万股。亚马逊权证从已归属 8.5942 万至最多 38.1922 万股，行权价 208.48 美元。求解器将同一股权池分配给普通股、零行权价奖励及权证公允价值，不再增加行权收入或权证股数稀释。'),
 'claimLimits':('Operating leases remain operating costs. Restricted cash is excluded. Other noncurrent liabilities and repatriation tax are explicit optional claim assumptions. The Casix litigation allegation of CNY400 million remains an unpriced tail risk; no probability or expected loss is invented. Gross warrant vesting and the volatility proxy are conditional. A nonpositive allocation pool gives zero ordinary-share value and separately retains the capital shortfall; operating EV remains signed.','经营租赁保留为经营成本，受限现金已排除。其他非流动负债及汇回税为明确可选请求权假设。Casix 诉讼所称人民币 4 亿元仍为未定价尾部风险，不虚构概率或预期损失。权证完整归属及波动率代理均有条件。分配池非正时普通股价值为零，同时单独保留资本缺口；经营企业价值仍保留正负号。'),
 'uncertainty':('No distribution calibration is established. All Monte Carlo defaults are fixed and Run is manual. The three named scenarios have no assigned probability. Each trial recomputes required-cash funding and jointly reprices warrants from intrinsic share value; selected claim counts, volatility, rate and term stay fixed. Blank selected claims block share allocation while valid operating value remains available.','尚未建立分布校准。蒙特卡洛默认值全部固定，须手动运行。三个命名情景不赋予概率。每次试验重新计算所需现金资金需求，并根据内在每股价值联立重估权证；选定请求权股数、波动率、利率及期限保持固定。选定请求权留空时阻止每股分配，但有效经营价值仍可显示。'),
 'history':('FY2017–2026 reported USD history retains field-level SEC provenance and later comparatives. Reported EBIT is the canonical operating history; Raytek gains and interest are outside EBIT. Cash-flow capex and accrued additions differ because of fixed-asset payables. The normalized capital series is an explicitly defined proxy, not verified market invested capital. Some early working-capital changes and ROIC observations remain unknown.','2017–2026 财年报告美元历史保留逐字段 SEC 来源及后续比较数据。报告 EBIT 为规范经营历史；Raytek 收益及利息不在 EBIT 内。由于固定资产应付款，现金流资本开支与应计新增资产不同。规范资本序列是明确定义的代理，并非已验证市场投入资本。部分早期营运资本变化及 ROIC 观察值保留未知。')}
